
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_xc_b97m_v_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_xc_b97m_v", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.471478066548641e+00, -5.357207481216590e+00, -5.197279577122953e+00, -4.975847275265770e+00, -4.673476379827554e+00, -4.267319137041171e+00, -3.731370332920968e+00, -3.040641491542720e+00, -2.206608212457560e+00, -1.368179524023365e+00, -7.791453727615535e-01, -6.433697302096958e-01, -6.654565687363156e-01, -5.552036670887803e-01, -3.699898834953730e-01, -2.214553034050929e-01, -1.192566825844309e-01, -5.287629983680885e-02, -1.492348687935725e-02, -2.083595713102578e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


